    """Collapse adjacent identical rows and columns."""
    rows = []
    for row in grid:
        if not rows or row != rows[-1]:
            rows.append(row[:])

    if not rows:
        return []
    out = []
    last_col = None
    for c in range(len(rows[0])):
        col = tuple(row[c] for row in rows)
        if c == 0 or col != last_col:
            for r, row in enumerate(rows):
                if r == 0:
                    out.append([])
                out[r].append(row[c])
        last_col = col
    return out
